export const replayStore = createStore<ReplayState & ReplayActions>()((set, get) => {
  const bump = (patch: Partial<ReplayState> = {}) => set({ ...patch, version: get().version + 1 });

  function row(r: StreamRow, d: Omit<Detection, "seq" | "wall">, now: number): void {
    const s = get();
    s.rows.unshift(r);
    if (s.rows.length > ROWS_KEEP) s.rows.length = ROWS_KEEP;
    const seq = s.detSeq + 1;
    pushCapped(s.detections, { ...d, seq, wall: now }, DETECTIONS_KEEP);
    let total = s.total;
    if (!s.seen.has(r.key)) {
      s.seen.add(r.key);
      total += 1;
    }
    bump({ detSeq: seq, total });
  }

  return {
    status: "idle",
    hello: null,
    version: 0,
    ...empty(),
    setStatus: (status) => bump({ status }),
    setError: (error) => bump({ error }),
    clearBuffers: () => {
      const s = get();
      bump({
        tracks: {},
        rf: [],
        rid: [],
        features: [],
        rows: [],
        detections: [],
        // the total, the recorder and the core keep counting real writes across seeks
        total: s.total,
        seen: s.seen,
      });
    },
    reset: () => bump({ status: "idle", hello: null, ...empty() }),
    apply: (m, now = performance.now()) => {
      const s = get();
      switch (m.type) {
        case "hello":
          bump({ hello: m, error: null });
          return;
        case "clock":
          bump({
            clock: { t_s: m.t_s, ts: m.ts, speed: m.speed, playing: m.playing },
            clockWall: now,
          });
          return;
        case "point": {
          const pts = (s.tracks[m.track_id] ??= []);
          if (m.x_m !== null && m.y_m !== null) {
            pushCapped(pts, { t_s: m.t_s, x: m.x_m, y: m.y_m, alt: m.alt_m ?? 0 }, TRACK_KEEP);
          }
          const key = `p:${m.track_id}:${m.t_s}`;
          row(
            {
              key,
              t_s: m.t_s,
              kind: "radar",
              sensor: m.sensor_id,
              x: m.x_m,
              y: m.y_m,
              alt: m.alt_m,
              value: m.quality,
              valueLabel: "quality",
            },
            {
              t_s: m.t_s,
              kind: "radar",
              sensor: m.sensor_id,
              track: m.track_id,
              x: m.x_m,
              y: m.y_m,
              alt: m.alt_m,
              bearing: null,
            },
            now,
          );
          return;
        }
        case "rf": {
          pushCapped(s.rf, m, 60);
          row(
            {
              key: `r:${m.sensor_id}:${m.t_s}:${m.bearing_deg}`,
              t_s: m.t_s,
              kind: "rf",
              sensor: m.sensor_id,
              x: null,
              y: null,
              alt: null,
              value: m.snr_db,
              valueLabel: "SNR",
            },
            {
              t_s: m.t_s,
              kind: "rf",
              sensor: m.sensor_id,
              track: null,
              x: null,
              y: null,
              alt: null,
              bearing: m.bearing_deg,
            },
            now,
          );
          return;
        }
        case "rid": {
          pushCapped(s.rid, m, 60);
          row(
            {
              key: `i:${m.serial}:${m.t_s}`,
              t_s: m.t_s,
              kind: "rid",
              sensor: m.serial,
              x: m.drone_x_m,
              y: m.drone_y_m,
              alt: null,
              value: null,
              valueLabel: "",
            },
            {
              t_s: m.t_s,
              kind: "rid",
              sensor: m.serial,
              track: null,
              x: m.drone_x_m,
              y: m.drone_y_m,
              alt: null,
              bearing: null,
            },
            now,
          );
          return;
        }
        case "features": {
          const f = s.features;
          if (f.length && (f[f.length - 1]?.t_s ?? -1) >= m.t_s) {
            const i = f.findIndex((x) => x.t_s >= m.t_s);
            if (i >= 0 && f[i]?.t_s === m.t_s) f[i] = m;
            else f.splice(i < 0 ? f.length : i, 0, m);
          } else f.push(m);
          const cut = m.t_s - FEATURES_WINDOW_S;
          while (f.length && (f[0]?.t_s ?? 0) <= cut) f.shift();
          bump();
          return;
        }
        case "ingest": {
          pushCapped(s.writeHistory, m.write_ms, WRITE_HISTORY);
          s.tables[m.table] = {
            rows: m.rows,
            total_rows: m.total_rows,
            write_ms: m.write_ms,
            statement: m.statement,
          };
          bump({ lastIngest: m, ingestCount: s.ingestCount + 1, ingestWall: now });
          return;
        }
      }
    },
  };
});

/** Detections per second over the last 5 replay seconds before the clock. */
export function detectionRate(s: ReplayState): number {
  const t = s.clock?.t_s;
  if (t === undefined) return 0;
  let n = 0;
  for (const r of s.rows) {
    if (r.t_s <= t - RATE_WINDOW_S) break; // rows are newest first
    if (r.t_s <= t) n += 1;
  }
  return n / RATE_WINDOW_S;
}

/** The replay clock now, interpolated from the last `clock` while playing (seconds). */
export function clockNow(s: ReplayState, now: number = performance.now()): number {
  const c = s.clock;
  if (!c) return 0;
  if (!c.playing) return c.t_s;
  const dt = Math.min(Math.max(0, (now - s.clockWall) / 1000), 0.25); // never run ahead > 1 tick
  const end = s.hello?.duration_s ?? Number.POSITIVE_INFINITY;
  return Math.min(c.t_s + c.speed * dt, end);
}

/** Total rows written to the live tables, from the last ingest per table. */
export function recordedTotal(s: ReplayState): number {
  return Object.values(s.tables).reduce((a, t) => a + t.total_rows, 0);
}
// Matcher results from the stream (SPEC §16.3): match, forecast, recall and the lens.
import { createStore } from "zustand/vanilla";

import type { DtwMsg, ForecastMsg, MatchMsg, RecallMsg } from "../api/messages";

export type Decision = "approved" | "rejected";

export interface MatchState {
  match: MatchMsg | null;
  forecast: ForecastMsg | null;
  recall: RecallMsg | null;
  dtw: DtwMsg | null;
  /** Bumps only when the top-3 set changes: entries appear once, as a discovery (§17.8). */
  entrance: number;
  top3: string;
  /** Decisions made in this session, by proposal seq (the next `match` carries the ledger's). */
  decisions: Record<number, Decision>;
  busy: Record<number, boolean>;
  error: string | null;
}

export interface MatchActions {
  apply: (m: MatchMsg | ForecastMsg | RecallMsg | DtwMsg) => void;
  clear: () => void;
  setBusy: (seq: number, busy: boolean) => void;
  decide: (seq: number, d: Decision) => void;
  setError: (e: string | null) => void;
}

export function top3Key(m: MatchMsg | null): string {
  return m
    ? m.matches
        .slice(0, 3)
        .map((x) => x.incident_id)
        .sort()
        .join("|")
    : "";
}

export const matchStore = createStore<MatchState & MatchActions>()((set, get) => ({
  match: null,
  forecast: null,
  recall: null,
  dtw: null,
  entrance: 0,
  top3: "",
  decisions: {},
  busy: {},
  error: null,
  apply: (m) => {
    switch (m.type) {
      case "match": {
        const key = top3Key(m);
        const s = get();
        set({ match: m, top3: key, entrance: key !== s.top3 ? s.entrance + 1 : s.entrance });
        return;
      }
      case "forecast":
        set({ forecast: m });
        return;
      case "recall":
        set({ recall: m });
        return;
      case "dtw":
        set({ dtw: m });
        return;
    }
  },
  clear: () => set({ match: null, forecast: null, recall: null, dtw: null, top3: "" }),
  setBusy: (seq, busy) => set({ busy: { ...get().busy, [seq]: busy } }),
  decide: (seq, d) => set({ decisions: { ...get().decisions, [seq]: d } }),
  setError: (error) => set({ error }),
}));

/** The decision for a match entry: this session's click, else what the ledger said. */
export function decisionOf(
  s: MatchState,
  seq: number | null,
  server: Decision | null,
): Decision | null {
  if (seq === null) return null;
  return s.decisions[seq] ?? server;
}
// UI preferences: reduce motion (OS setting or M), camera preset, performance level (§17.11).
import { createStore } from "zustand/vanilla";

export type CameraPreset = "overview" | "follow" | "target" | "memory" | "swarm";

export interface UiState {
  osReduce: boolean;
  /** M toggles it; null follows the OS. */
  userReduce: boolean | null;
  camera: CameraPreset;
  /** 0 full effects, 1 bloom off, 2 bloom off and packets halved (auto-degrade). */
  perfLevel: 0 | 1 | 2;
  shortcutsOpen: boolean;
}

export interface UiActions {
  setOsReduce: (v: boolean) => void;
  toggleReduce: () => void;
  setCamera: (c: CameraPreset) => void;
  setPerfLevel: (l: 0 | 1 | 2) => void;
  setShortcuts: (open: boolean) => void;
}

export const uiStore = createStore<UiState & UiActions>()((set, get) => ({
  osReduce: false,
  userReduce: null,
  camera: "overview",
  perfLevel: 0,
  shortcutsOpen: false,
  setOsReduce: (osReduce) => set({ osReduce }),
  toggleReduce: () => set({ userReduce: !reduceMotion(get()) }),
  setCamera: (camera) => set({ camera }),
  setPerfLevel: (perfLevel) => set({ perfLevel }),
  setShortcuts: (shortcutsOpen) => set({ shortcutsOpen }),
}));

export function reduceMotion(s: UiState): boolean {
  return s.userReduce ?? s.osReduce;
}

/** Bloom and vignette run only at full motion and full performance. */
export function effectsOn(s: UiState): boolean {
  return !reduceMotion(s) && s.perfLevel === 0;
}

export const PACKET_BUDGET = 300;

export function packetBudget(s: UiState): number {
  if (reduceMotion(s)) return 0; // §17.11: no particles in reduce motion
  return s.perfLevel >= 2 ? PACKET_BUDGET / 2 : PACKET_BUDGET;
}
// The ledger chain panel's state (SPEC §17.6): blocks by seq, the verify result, the open record.
import { createStore } from "zustand/vanilla";

import type { LedgerBlock, LedgerRecord, LedgerVerify } from "../api/messages";

export const BLOCKS_KEEP = 24;

export interface CaseState {
  blocks: LedgerBlock[];
  /** performance.now() when each block arrived live (the slide-in and connector draw). */
  arrived: Record<number, number>;
  verify: LedgerVerify | null;
  verifyError: string | null;
  selected: LedgerRecord | null;
}

export interface CaseActions {
  addBlocks: (bs: LedgerBlock[], live?: boolean, now?: number) => void;
  setVerify: (v: LedgerVerify | null, error?: string | null) => void;
  select: (r: LedgerRecord | null) => void;
  reset: () => void;
}

export const caseStore = createStore<CaseState & CaseActions>()((set, get) => ({
  blocks: [],
  arrived: {},
  verify: null,
  verifyError: null,
  selected: null,
  addBlocks: (bs, live = false, now = performance.now()) => {
    const s = get();
    const by = new Map(s.blocks.map((b) => [b.seq, b]));
    const arrived = { ...s.arrived };
    for (const b of bs) {
      if (live && !by.has(b.seq)) arrived[b.seq] = now;
      by.set(b.seq, b);
    }
    const blocks = [...by.values()].sort((a, b) => a.seq - b.seq).slice(-BLOCKS_KEEP);
    set({ blocks, arrived });
  },
  setVerify: (verify, verifyError = null) => set({ verify, verifyError }),
  select: (selected) => set({ selected }),
  reset: () => set({ blocks: [], arrived: {}, verify: null, verifyError: null, selected: null }),
}));

/** The chain head the panel shows (highest seq). */
export function headSeq(s: CaseState): number | null {
  return s.blocks.length ? (s.blocks[s.blocks.length - 1]?.seq ?? null) : null;
}
// Route each stream message to its store (SPEC §16.3). A `clock` with `seeked` drops the
// buffers: the server follows it with a catch-up of the last 120 s and the current result.
import { toBlock, type StreamMessage } from "../api/messages";
import { caseStore } from "./caseStore";
import { matchStore } from "./matchStore";
import { replayStore } from "./replayStore";

export function dispatch(m: StreamMessage, now: number = performance.now()): void {
  const replay = replayStore.getState();
  switch (m.type) {
    case "clock":
      if (m.seeked) {
        replay.clearBuffers();
        matchStore.getState().clear();
      }
      replay.apply(m, now);
      return;
    case "hello":
    case "point":
    case "rf":
    case "rid":
    case "features":
    case "ingest":
      replay.apply(m, now);
      return;
    case "match":
    case "forecast":
    case "recall":
    case "dtw":
      matchStore.getState().apply(m);
      return;
    case "ledger":
      caseStore.getState().addBlocks([toBlock(m)], true, now);
      return;
    case "error":
      replay.setError(m.message);
      return;
  }
}
// The open replay stream, for the command bar and keyboard shortcuts.
import type { ReplayStream } from "../api/stream";

let current: ReplayStream | null = null;

export function setStream(s: ReplayStream | null): void {
  current = s;
}

export const controls = {
  play: () => current?.play(),
  pause: () => current?.pause(),
  restart: () => current?.seek(0),
  seek: (t: number) => current?.seek(t),
  speed: (v: 1 | 2 | 5) => current?.setSpeed(v),
  dtw: (track: string, channel?: string) => current?.requestDtw(track, channel),
  connected: () => current !== null,
};
// Open one replay stream for the page's lifetime, plus the ledger tail and verify state.
import { useEffect, useState } from "react";

import { api } from "../api/client";
import type { Scene } from "../api/messages";
import { ReplayStream, replayUrl } from "../api/stream";
import { caseStore } from "./caseStore";
import { setStream } from "./controls";
import { dispatch } from "./dispatch";
import { matchStore } from "./matchStore";
import { replayStore } from "./replayStore";

/** Re-check the chain whenever the head moves (debounced: a batch of 3 proposals is one check). */
function watchVerify(): () => void {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let head = -1;
  const check = () =>
    api
      .ledgerVerify()
      .then((v) => caseStore.getState().setVerify(v))
      .catch((e: unknown) => caseStore.getState().setVerify(null, String(e)));
  const unsub = caseStore.subscribe((s) => {
    const h = s.blocks[s.blocks.length - 1]?.seq ?? -1;
    if (h === head) return;
    head = h;
    if (timer) clearTimeout(timer);
    timer = setTimeout(check, 400);
  });
  check();
  return () => {
    unsub();
    if (timer) clearTimeout(timer);
  };
}

export function useReplay(incidentId: string): { scene: Scene | null; sceneError: string | null } {
  const [scene, setScene] = useState<Scene | null>(null);
  const [sceneError, setSceneError] = useState<string | null>(null);
  const installation = useInstallation();

  useEffect(() => {
    replayStore.getState().reset();
    matchStore.getState().clear();
    caseStore.getState().reset();
    const stream = new ReplayStream({
      url: replayUrl(incidentId),
      onMessage: (m) => dispatch(m),
      onStatus: (s) => replayStore.getState().setStatus(s),
    });
    setStream(stream);
    stream.connect();
    api
      .ledgerTail(12)
      .then((bs) => caseStore.getState().addBlocks(bs))
      .catch(() => undefined);
    const stopVerify = watchVerify();
    return () => {
      stopVerify();
      setStream(null);
      stream.close();
    };
  }, [incidentId]);

  useEffect(() => {
    if (!installation) return;
    let alive = true;
    api
      .scene(installation)
      .then((s) => alive && setScene(s))
      .catch((e: unknown) => alive && setSceneError(String(e instanceof Error ? e.message : e)));
    return () => {
      alive = false;
    };
  }, [installation]);

  return { scene, sceneError };
}

function useInstallation(): string | null {
  const [id, setId] = useState<string | null>(
    replayStore.getState().hello?.installation_id ?? null,
  );
  useEffect(
    () =>
      replayStore.subscribe((s) => {
        const next = s.hello?.installation_id ?? null;
        setId((prev) => (prev === next ? prev : next));
      }),
    [],
  );
  return id;
}

