// Typed REST client (SPEC §16.4). Same origin: Vite proxies /api in dev, FastAPI serves both in
// the demo. Errors carry the server's message (FastAPI's `detail`).
import type {
  EvidenceLine,
  Health,
  IncidentSummary,
  LedgerBlock,
  LedgerRecord,
  LedgerVerify,
  LinkResponse,
  Scene,
} from "./messages";

/** The analyst handle the Command Center approves as (D-112), as `memory demo` does. */
export const ANALYST = "demo";

export class ApiError extends Error {
  readonly status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type Fetch = typeof fetch;
let fetchImpl: Fetch = (...args) => fetch(...args);

/** Tests replace the transport. */
export function setFetch(f: Fetch): void {
  fetchImpl = f;
}

async function detail(r: Response): Promise<string> {
  try {
    const body: unknown = await r.json();
    if (body && typeof body === "object" && "detail" in body) {
      const d = (body as { detail: unknown }).detail;
      return typeof d === "string" ? d : JSON.stringify(d);
    }
  } catch {
    // not JSON
  }
  return `${r.status} ${r.statusText}`;
}

async function getJson<T>(path: string): Promise<T> {
  const r = await fetchImpl(path, { headers: { Accept: "application/json" } });
  if (!r.ok) throw new ApiError(r.status, await detail(r));
  return (await r.json()) as T;
}

async function postJson<T>(path: string, body: unknown): Promise<T> {
  const r = await fetchImpl(path, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new ApiError(r.status, await detail(r));
  return (await r.json()) as T;
}

export const api = {
  health: () => getJson<Health>("/api/health"),
  scene: (installationId: string) =>
    getJson<Scene>(`/api/installations/${encodeURIComponent(installationId)}/scene`),
  liveIncidents: () => getJson<IncidentSummary[]>("/api/incidents?status=live"),
  ledgerTail: (n = 12) => getJson<LedgerBlock[]>(`/api/ledger/tail?n=${n}`),
  ledgerRecord: (seq: number) => getJson<LedgerRecord>(`/api/ledger/${seq}`),
  ledgerVerify: () => getJson<LedgerVerify>("/api/ledger/verify"),
  /** Approve or reject a proposal (rule 8: only this explicit click commits a link). */
  decideLink: (
    caseId: string,
    proposalSeq: number,
    decision: "approve" | "reject",
    clock: string,
  ) =>
    postJson<LinkResponse>(`/api/cases/${encodeURIComponent(caseId)}/links`, {
      proposal_seq: proposalSeq,
      decision,
      analyst: ANALYST,
      clock,
    }),
  /** Export an evidence package; `onLine` gets each NDJSON line as the server hashes files. */
  exportEvidence: async (caseId: string, onLine: (l: EvidenceLine) => void): Promise<void> => {
    const r = await fetchImpl(`/api/cases/${encodeURIComponent(caseId)}/evidence`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ approve: true, analyst: ANALYST }),
    });
    if (!r.ok) throw new ApiError(r.status, await detail(r));
    await readNdjson(r, onLine);
  },
};

/** Parse an NDJSON response line by line as it arrives. */
export async function readNdjson<T>(r: Response, onLine: (l: T) => void): Promise<void> {
  if (!r.body) {
    for (const line of (await r.text()).split("\n")) if (line.trim()) onLine(JSON.parse(line) as T);
    return;
  }
  const reader = r.body.getReader();
  const dec = new TextDecoder();
  let buf = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (value) buf += dec.decode(value, { stream: !done });
    let i: number;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i).trim();
      buf = buf.slice(i + 1);
      if (line) onLine(JSON.parse(line) as T);
    }
    if (done) break;
  }
  if (buf.trim()) onLine(JSON.parse(buf) as T);
}
// Names for the generated OpenAPI types (SPEC §16.5). Never edit types.gen.ts by hand: change
// api/schemas.py, then `kairos-defense api --dump-openapi web/openapi.json && npm run gen:types`.
import type { components } from "./types.gen";

type S = components["schemas"];

export type HelloMsg = S["HelloMsg"];
export type ClockMsg = S["ClockMsg"];
export type PointMsg = S["PointMsg"];
export type RfMsg = S["RfMsg"];
export type RidMsg = S["RidMsg"];
export type FeaturesMsg = S["FeaturesMsg"];
export type IngestMsg = S["IngestMsg"];
export type MatchMsg = S["MatchMsg"];
export type MatchItem = S["MatchItem"];
export type DtwMsg = S["DtwMsg"];
export type ForecastMsg = S["ForecastMsg"];
export type RecallMsg = S["RecallMsg"];
export type LedgerMsg = S["LedgerMsg"];
export type ErrorMsg = S["ErrorMsg"];

export type StreamMessage =
  | HelloMsg
  | ClockMsg
  | PointMsg
  | RfMsg
  | RidMsg
  | FeaturesMsg
  | IngestMsg
  | MatchMsg
  | DtwMsg
  | ForecastMsg
  | RecallMsg
  | LedgerMsg
  | ErrorMsg;

export type StreamType = StreamMessage["type"];

export const STREAM_TYPES: readonly StreamType[] = [
  "hello",
  "clock",
  "point",
  "rf",
  "rid",
  "features",
  "ingest",
  "match",
  "dtw",
  "forecast",
  "recall",
  "ledger",
  "error",
];

export type ClientMessage =
  S["PlayCmd"] | S["PauseCmd"] | S["SeekCmd"] | S["SpeedCmd"] | S["DtwCmd"];

export type Scene = S["Scene"];
export type IncidentSummary = S["IncidentSummary"];
export type LedgerBlock = S["LedgerBlock"];
export type LedgerRecord = S["LedgerRecord"];
export type LedgerVerify = S["LedgerVerify"];
export type LinkResponse = S["LinkResponse"];
export type Health = S["Health"];
export type EvidenceFileLine = S["EvidenceFileLine"];
export type EvidenceDoneLine = S["EvidenceDoneLine"];
export type EvidenceErrorLine = S["EvidenceErrorLine"];
export type EvidenceLine = EvidenceFileLine | EvidenceDoneLine | EvidenceErrorLine;

/** A ledger message as a chain block (the stream adds only `type`). */
export function toBlock(m: LedgerMsg): LedgerBlock {
  return {
    seq: m.seq,
    event_type: m.event_type,
    actor: m.actor,
    recorded_at: m.recorded_at,
    hash: m.hash,
    prev_hash: m.prev_hash,
    case_id: m.case_id,
    subject_id: m.subject_id,
  };
}
import { useEffect } from "react";

import { Home } from "../pages/Home";
import { LiveWatch } from "../pages/LiveWatch";
import { NotFound, Planned } from "../pages/Planned";
import { prefersReducedMotion } from "../theme/motion";
import { uiStore } from "../state/uiStore";
import { CommandBar } from "./CommandBar";
import { PLANNED, useRoute } from "./routes";
import { ShortcutsDialog } from "./Shortcuts";
import { useShortcuts } from "./keys";

function useOsReducedMotion(): void {
  useEffect(() => {
    uiStore.getState().setOsReduce(prefersReducedMotion());
