import { MatchList } from "../panels/MatchList";
import { Recorder } from "../panels/Recorder";
import { Signals } from "../panels/Signals";
import { StreamPanel } from "../panels/Stream";
import { Theater } from "../three/Theater";
import { useReplay } from "../state/useReplay";

/** Keeps the DOM panels alive if WebGL fails (headless browsers, old GPUs). */
class TheaterBoundary extends Component<{ children: ReactNode }, { error: string | null }> {
  override state = { error: null as string | null };
  static getDerivedStateFromError(e: unknown) {
    return { error: e instanceof Error ? e.message : String(e) };
  }
  override render() {
    if (this.state.error)
      return (
        <div role="alert" className="grid h-full place-items-center p-8 text-center">
          <div>
            <p className="text-15 text-ink-hi">The 3D theater could not start.</p>
            <p className="mt-1 text-13 text-ink-mid">{this.state.error}</p>
          </div>
        </div>
      );
    return this.props.children;
  }
}

/**
 * Live watch (SPEC §17.2): the theater is the hero, the memory rail docks on the right and the
 * instrument rail along the bottom. Below 1280 px the rails stack under the theater.
 */
export function LiveWatch({ incidentId }: { incidentId: string }) {
  const { scene, sceneError } = useReplay(incidentId);
  const trail = ["Live watch", scene?.name ?? incidentId];
  return (
    <>
      <CommandBar trail={trail} replay />
      <div
        data-testid="live-watch"
        className="grid min-h-0 flex-1 grid-cols-1 gap-2 overflow-y-auto p-2 xl:grid-cols-[minmax(0,1fr)_25rem] xl:grid-rows-[minmax(0,1fr)_17rem] xl:overflow-hidden 2xl:grid-cols-[minmax(0,1fr)_28rem] 2xl:grid-rows-[minmax(0,1fr)_19rem]"
      >
        <main
          aria-label="Live theater"
          className="relative min-h-[28rem] overflow-hidden rounded-panel border border-hairline xl:col-start-1 xl:row-start-1 xl:min-h-0"
        >
          <TheaterBoundary>
            <Theater scene={scene} />
          </TheaterBoundary>
          {sceneError ? (
            <p role="alert" className="absolute top-3 left-3 text-13 text-alert">
              Scene: {sceneError}
            </p>
          ) : null}
        </main>
        <aside
          aria-label="Memory rail"
          className="flex min-h-[20rem] flex-col gap-2 xl:col-start-2 xl:row-span-2 xl:row-start-1 xl:min-h-0"
        >
          <MatchList />
        </aside>
        <section
          aria-label="Instrument rail"
          className="grid min-h-[17rem] grid-cols-1 gap-2 md:grid-cols-2 xl:col-start-1 xl:row-start-2 xl:min-h-0 xl:grid-cols-[1.45fr_1.2fr_0.95fr_1fr]"
        >
          <StreamPanel />
          <Signals />
          <Recorder />
          <LedgerChain />
        </section>
      </div>
    </>
  );
}
import { useEffect, useState } from "react";

import { api } from "../api/client";
import { navigate } from "../app/routes";

/** `/`: open Live watch for the first live single-track incident. */
export function Home() {
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    let alive = true;
    api
      .liveIncidents()
      .then((list) => {
        if (!alive) return;
        const first = list.find((i) => !i.is_swarm) ?? list[0];
        if (first) navigate(`/live/${first.incident_id}`, true);
        else setError("No live incident in the data. Run make data index models.");
      })
      .catch((e: unknown) => alive && setError(String(e instanceof Error ? e.message : e)));
    return () => {
      alive = false;
    };
  }, []);
  return (
    <main aria-labelledby="home-title" className="grid flex-1 place-items-center p-8">
      <div className="max-w-md text-center">
        <h1 id="home-title" className="text-18 font-bold text-ink-hi">
          {error ? "No replay loaded" : "Opening Live watch"}
        </h1>
        {error ? <p className="mt-2 text-15 text-ink-mid">{error}</p> : null}
      </div>
    </main>
  );
}
import { PLANNED, type PlannedPage } from "../app/routes";

/** A page another phase builds: one plain sentence, no fake data (rule 10). */
export function Planned({ page }: { page: PlannedPage }) {
  const p = PLANNED[page];
  return (
    <main aria-labelledby="planned-title" className="grid flex-1 place-items-center p-8">
      <div className="max-w-md text-center">
        <h1 id="planned-title" className="text-18 font-bold text-ink-hi">
          {p.title}
        </h1>
        <p className="mt-2 text-15 text-ink-mid">
          The {p.title.toLowerCase()} arrives in phase {p.phase}. Live watch is ready now.
        </p>
      </div>
    </main>
  );
}

export function NotFound({ path }: { path: string }) {
  return (
    <main aria-labelledby="nf-title" className="grid flex-1 place-items-center p-8">
      <div className="max-w-md text-center">
        <h1 id="nf-title" className="text-18 font-bold text-ink-hi">
          No page at {path}
        </h1>
        <p className="mt-2 text-15 text-ink-mid">Use the Pages menu to open Live watch.</p>
      </div>
    </main>
  );
}
import type { ReactNode } from "react";

/** A docked instrument (SPEC §17.1): glass, hairline border, 6 px radius, a 13 px bold title. */
export function Panel(props: {
  id: string;
  title: string;
  /** Right side of the title row: live readouts. */
  meta?: ReactNode;
  className?: string;
  children: ReactNode;
}) {
  return (
    <section
      aria-labelledby={`${props.id}-title`}
      data-testid={`panel-${props.id}`}
      className={`flex min-h-0 min-w-0 flex-col rounded-panel border border-hairline bg-glass backdrop-blur-glass ${props.className ?? ""}`}
    >
      <header className="flex items-baseline justify-between gap-3 px-3 pt-2 pb-1">
        <h2
          id={`${props.id}-title`}
          className="shrink-0 text-13 font-bold whitespace-nowrap text-ink-mid"
        >
          {props.title}
        </h2>
        {props.meta ? (
          <div className="min-w-0 truncate text-12 text-ink-mid">{props.meta}</div>
        ) : null}
      </header>
      <div className="relative min-h-0 flex-1">{props.children}</div>
    </section>
  );
}
import { useEffect, useRef } from "react";

import { api } from "../api/client";
import type { MatchItem } from "../api/messages";
import { baseName, localDate, ms, tPlus } from "../lib/format";
import { useThrottledStore } from "../lib/useThrottledStore";
import { caseStore } from "../state/caseStore";
import { decisionOf, matchStore, type Decision } from "../state/matchStore";
import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import { animate, EASE_OUT } from "./anim";
import { Panel } from "./Panel";
import { ScoreRing } from "./ScoreRing";

const NO_PROPOSAL = "No proposal was written for this match: no case to link it to yet";

/** "flown 18% slower" from a warp ratio (the matcher's wording, §10.4), or null within ±10%. */
function warpText(k: number | null): string | null {
  if (k === null || !Number.isFinite(k) || k <= 0) return null;
  if (k > 1.1) return `flown ${Math.round((1 - 1 / k) * 100)}% slower`;
  if (k < 0.9) return `flown ${Math.round((1 / k - 1) * 100)}% faster`;
  return null;
}

async function decide(caseId: string | null, m: MatchItem, d: "approve" | "reject") {
  const seq = m.proposal_seq;
  if (caseId === null || seq === null) return;
  const st = matchStore.getState();
  const r = replayStore.getState();
  const clock = r.clock?.ts ?? r.hello?.start_ts ?? new Date().toISOString();
  st.setBusy(seq, true);
  st.setError(null);
  try {
    const res = await api.decideLink(caseId, seq, d, clock);
    matchStore.getState().decide(seq, d === "approve" ? "approved" : "rejected");
    caseStore.getState().addBlocks([res.block], true);
  } catch (e: unknown) {
    matchStore.getState().setError(e instanceof Error ? e.message : String(e));
  } finally {
    matchStore.getState().setBusy(seq, false);
  }
}

function Entry(props: {
  m: MatchItem;
  index: number;
  caseId: string | null;
  decision: Decision | null;
  busy: boolean;
  reduce: boolean;
}) {
  const { m, decision, reduce } = props;
  const ref = useRef<HTMLLIElement>(null);
  useEffect(() => {
    animate(
      ref.current,
      [
        { opacity: 0, transform: "translateY(6px)" },
        { opacity: 1, transform: "translateY(0)" },
      ],
      { duration: 240, delay: props.index * 120, easing: EASE_OUT, fill: "backwards" },
      reduce,
    );
    // mount only: entries appear once per new top-3 set (§17.8)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const name = `${baseName(m.installation_id)}, ${localDate(m.local_start)}`;
  const pace = warpText(m.warp_ratio);
  const showPace = pace !== null && !m.reasons.some((r) => r.includes("flown"));
  const disabled = m.proposal_seq === null || props.busy || decision !== null;
  const title =
    m.proposal_seq === null ? NO_PROPOSAL : decision !== null ? `Link ${decision}` : undefined;
  return (
    <li
      ref={ref}
      data-testid="match-entry"
      data-incident={m.incident_id}
      className="flex gap-3 border-b border-hairline px-3 py-3 last:border-b-0"
    >
      <ScoreRing score={m.score} state={decision ?? "pending"} reduce={reduce} />
      <div className="min-w-0 flex-1">
        <div className="flex items-baseline justify-between gap-2">
          <h3 className="truncate text-15 font-bold text-ink-hi">{name}</h3>
          <span data-testid="match-score" className="font-mono text-15 text-afterglow">
            {m.score.toFixed(2)}
          </span>
        </div>
        <p className="truncate text-12 text-ink-mid" title={m.incident_id}>
          {m.incident_id}
        </p>
        <ul aria-label="Reasons" className="mt-1.5 flex flex-wrap gap-1">
          {m.reasons.map((r) => (
            <li
              key={r}
              data-testid="reason-chip"
              className="rounded-chip border border-hairline px-2 py-0.5 text-12 text-ink-hi"
            >
              {r}
            </li>
          ))}
          {showPace ? (
            <li className="rounded-chip border border-hairline px-2 py-0.5 text-12 text-ink-hi">
              {pace}
            </li>
          ) : null}
        </ul>
        <p
          data-testid="memory-status"
          className={`mt-1.5 text-13 ${m.memory_status.startsWith("Closed") ? "text-afterglow" : "text-ink-mid"}`}
        >
          {m.memory_status}
        </p>
        <div className="mt-2 flex items-center gap-2">
          <button
            type="button"
            aria-label={`Approve link: ${name}`}
            title={title}
            disabled={disabled}
            onClick={() => void decide(props.caseId, m, "approve")}
            className="rounded-button border border-hairline px-3 py-1 text-13 text-ink-hi transition-colors duration-(--dur-micro) ease-(--ease-out) hover:border-verified disabled:cursor-not-allowed disabled:text-ink-mid disabled:hover:border-hairline"
          >
            Approve link
          </button>
          <button
            type="button"
            aria-label={`Reject: ${name}`}
            title={title}
            disabled={disabled}
            onClick={() => void decide(props.caseId, m, "reject")}
            className="rounded-button border border-hairline px-3 py-1 text-13 text-ink-mid transition-colors duration-(--dur-micro) ease-(--ease-out) hover:border-alert hover:text-ink-hi disabled:cursor-not-allowed disabled:hover:border-hairline disabled:hover:text-ink-mid"
          >
            Reject
          </button>
          {decision ? (
            <span
              data-testid="match-decision"
              className={`text-13 ${decision === "approved" ? "text-verified" : "text-ink-mid"}`}
            >
              {decision === "approved" ? "Linked" : "Rejected"}
            </span>
          ) : null}
        </div>
      </div>
    </li>
  );
}

/** The memory rail's match list (§17.8): three entries, best first, approve or reject each. */
export function MatchList() {
  const s = useThrottledStore(matchStore, (st) => ({
    match: st.match,
    entrance: st.entrance,
    busy: st.busy,
    error: st.error,
    decisions: st.decisions,
    state: st,
  }));
  const hello = useThrottledStore(replayStore, (st) => st.hello);
  const reduce = useThrottledStore(uiStore, reduceMotion);
  const m = s.match;

  let waiting = "Waiting for the replay";
  if (hello)
    waiting =
      hello.matching === false
        ? "Swarm matching arrives in phase 9"
        : `The matcher starts at ${tPlus(hello.min_track_s)}`;

  return (
    <Panel
      id="matchlist"
      title="Matches"
      className="flex-1"
      meta={m ? `At ${tPlus(m.t_s)}` : undefined}
    >
      <div className="absolute inset-0 flex flex-col overflow-y-auto">
        {!m || m.matches.length === 0 ? (
          <p data-testid="match-waiting" className="px-3 py-2 text-13 text-ink-mid">
            {m ? "No earlier flight to match" : waiting}
          </p>
        ) : (
          <>
            <ol aria-label="Best matches, best first" className="flex flex-col">
              {m.matches.slice(0, 3).map((x, i) => (
                <Entry
                  // a new top-3 set remounts (and animates) its entries; a rerun does not
                  key={`${s.entrance}:${x.incident_id}`}
                  m={x}
                  index={i}
                  caseId={m.case_id}
                  decision={decisionOf(s.state, x.proposal_seq, x.decision ?? null)}
                  busy={x.proposal_seq !== null && s.busy[x.proposal_seq] === true}
                  reduce={reduce}
                />
              ))}
            </ol>
            {s.error ? (
              <p role="alert" className="px-3 py-2 text-13 text-alert">
                {s.error}
              </p>
            ) : null}
            <p data-testid="match-model" className="mt-auto px-3 py-2 text-12 text-ink-mid">
              Model {m.model_version}, computed in {ms(m.elapsed_ms)}
              {m.cached ? " (cached)" : ""}
              {m.case_id ? `; proposals go to ${m.case_id}` : "; no case to propose links to"}
            </p>
          </>
        )}
      </div>
    </Panel>
  );
}

