import { Canvas, useFrame } from "@react-three/fiber";
import { memo, useMemo, useRef } from "react";

import type { Scene } from "../api/messages";
import { useThrottledStore } from "../lib/useThrottledStore";
import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore, type CameraPreset } from "../state/uiStore";
import { token } from "../theme/colors";
import { OVERVIEW } from "./camera";
import { CameraRig } from "./CameraRig";
import { Core } from "./Core";
import { Drone } from "./Drone";
import { Effects } from "./Effects";
import { Ground } from "./Ground";
import { Installation } from "./Installation";
import { Packets } from "./Packets";
import { PERF_START, perfLabel, stepPerf } from "./perf";
import { Radar } from "./Radar";
import { Rf } from "./Rf";
import { Roads } from "./Roads";
import type { Origin } from "./sceneMath";
import { theaterSummary } from "./summary";

/** One Drone per live track (the set changes rarely: checked once a second). */
function Drones({ origin }: { origin: Origin }) {
  const ids = useThrottledStore(replayStore, (s) => Object.keys(s.tracks).sort().join("|"), 1);
  return (
    <>{ids ? ids.split("|").map((id) => <Drone key={id} trackId={id} origin={origin} />) : null}</>
  );
}

/** Auto-degrade (§17.11): feeds every frame's time into the policy. */
function PerfMonitor() {
  const st = useRef(PERF_START);
  useFrame((_, dt) => {
    const next = stepPerf(st.current, dt * 1000, performance.now() / 1000);
    if (next.level !== st.current.level) uiStore.getState().setPerfLevel(next.level);
    st.current = next;
  });
  return null;
}

const SceneContent = memo(function SceneContent({ scene }: { scene: Scene }) {
  const origin = useMemo(() => ({ x: scene.origin_x_m, y: scene.origin_y_m }), [scene]);
  const radar = scene.sensors.find((s) => s.kind === "radar");
  const rfs = scene.sensors.filter((s) => s.kind === "rf");
  return (
    <>
      <Installation scene={scene} origin={origin} />
      <Roads roads={scene.roads} origin={origin} />
      {radar ? <Radar sensor={radar} origin={origin} /> : null}
      {rfs.map((s) => (
        <Rf key={s.sensor_id} sensor={s} origin={origin} />
      ))}
      <Drones origin={origin} />
      <Packets scene={scene} origin={origin} />
      <CameraRig scene={scene} origin={origin} />
    </>
  );
});

const PRESETS: [CameraPreset, string][] = [
  ["overview", "Overview"],
  ["follow", "Follow"],
  ["target", "Target"],
];

function CameraButtons() {
  const cam = useThrottledStore(uiStore, (s) => s.camera, 10);
  return (
    <div
      role="group"
      aria-label="Camera"
      className="absolute top-2 right-2 flex gap-1 rounded-panel border border-hairline bg-glass p-1 backdrop-blur-glass"
    >
      {PRESETS.map(([id, label]) => (
        <button
          key={id}
          type="button"
          aria-pressed={cam === id}
          onClick={() => uiStore.getState().setCamera(id)}
          className={`rounded-button px-2 py-1 text-13 transition-colors duration-(--dur-micro) ease-(--ease-out) ${
            cam === id ? "bg-hairline text-flash" : "text-ink-mid hover:text-ink-hi"
          }`}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

function Summary() {
  const text = useThrottledStore(replayStore, (s) => theaterSummary(s), 1);
  return (
    <p className="sr-only" aria-live="polite" data-testid="theater-summary">
      {text}
    </p>
  );
}

/**
 * The live theater (SPEC §17.3): the installation in local meters, the radar and RF sensors, the
 * live tracks, data packets and the Kairos core, all driven by stream events and the replay clock.
 */
export function Theater({ scene }: { scene: Scene | null }) {
  const perf = useThrottledStore(uiStore, (s) => perfLabel(s.perfLevel, reduceMotion(s)), 4);
  const background = token("--scope");
  return (
    <div data-testid="theater" data-perf={perf} className="relative h-full w-full bg-scope">
      <Canvas
        dpr={[1, 2]}
        gl={{ antialias: true, powerPreference: "high-performance" }}
        camera={{ fov: 45, near: 5, far: 40000, position: OVERVIEW.position }}
        aria-hidden="true"
      >
        <color attach="background" args={[background]} />
        <Ground />
        <Core />
        {scene ? <SceneContent scene={scene} /> : <CameraRig scene={null} origin={null} />}
        <PerfMonitor />
        <Effects />
      </Canvas>
      {scene ? null : (
        <p className="absolute top-3 left-3 text-13 text-ink-mid">Loading the installation</p>
      )}
      <CameraButtons />
      <Summary />
    </div>
  );
}
// Camera shots for the theater presets (§17.3). Scene meters; see sceneMath for the frame.
import type { CameraPreset } from "../state/uiStore";
import { bearingVector, type Vec3 } from "./sceneMath";

export interface Shot {
  position: Vec3;
  target: Vec3;
}

/** Overview: the fence, the 3.5 km radar ring and the core, seen from the south. */
export const OVERVIEW: Shot = { position: [300, 3100, 4500], target: [300, 0, 450] };

/** Static presets; follow and target depend on the live data. */
export const PRESETS: Record<Exclude<CameraPreset, "follow" | "target">, Shot> = {
  overview: OVERVIEW,
  memory: { position: [0, 9000, 11000], target: [0, 0, 0] }, // phase 8: frames the ghosts
  swarm: OVERVIEW, // phase 9
};

export const FOLLOW_BACK_M = 400;
export const FOLLOW_UP_M = 180;
export const TARGET_M = 900;

/** Chase shot: 400 m behind the drone along its heading, a little above. */
export function followShot(drone: Vec3, headingDeg: number | null): Shot {
  const d = bearingVector(headingDeg ?? 0);
  return {
    position: [
      drone[0] - FOLLOW_BACK_M * d[0],
      drone[1] + FOLLOW_UP_M,
      drone[2] - FOLLOW_BACK_M * d[2],
    ],
    target: drone,
  };
}

/** Target shot: 900 m from the target asset, from the south at about 35° elevation. */
export function targetShot(at: Vec3): Shot {
  const el = (35 * Math.PI) / 180;
  return {
    position: [at[0], TARGET_M * Math.sin(el), at[2] + TARGET_M * Math.cos(el)],
    target: [at[0], 0, at[2]],
  };
}
import { CameraControls } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useEffect, useRef } from "react";

import type { Scene } from "../api/messages";
import { useThrottledStore } from "../lib/useThrottledStore";
import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import { followShot, PRESETS, targetShot } from "./camera";
import { toScene, type Origin, type Vec3 } from "./sceneMath";

/**
 * Camera presets with 1.2 s damped transitions (instant in reduce motion) and free orbit
 * otherwise (§17.3). Follow tracks the latest real detection; target frames the identified asset.
 */
export function CameraRig({ scene, origin }: { scene: Scene | null; origin: Origin | null }) {
  const ref = useRef<CameraControls>(null);
  const aimed = useRef<string | null>(null);
  const first = useRef(true);
  const preset = useThrottledStore(uiStore, (s) => s.camera, 10);

  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    c.smoothTime = 0.35; // ≈ 1.2 s to settle
    const smooth = !first.current && !reduceMotion(uiStore.getState());
    first.current = false;
    aimed.current = null;
    if (preset === "follow" || preset === "target") return; // from the live data, below
    const s = PRESETS[preset];
    void c.setLookAt(...s.position, ...s.target, smooth);
  }, [preset]);

  useFrame(() => {
    const c = ref.current;
    if (!c || !origin || (preset !== "follow" && preset !== "target")) return;
    const s = replayStore.getState();
    const smooth = !reduceMotion(uiStore.getState());
    const f = s.features[s.features.length - 1];
    if (preset === "follow") {
      const id = s.hello?.tracks[0];
      const pts = id ? s.tracks[id] : undefined;
      const last = pts?.[pts.length - 1];
      if (!last) return;
      const shot = followShot(toScene(last.x, last.y, last.alt, origin), f?.heading_deg ?? null);
      void c.setLookAt(...shot.position, ...shot.target, smooth);
      return;
    }
    const asset = scene?.assets.find((a) => a.asset_id === f?.target_asset_id);
    const at = asset
      ? toScene(asset.centroid_x_m, asset.centroid_y_m, 0, origin)
      : ([0, 0, 0] as Vec3);
    const shot = targetShot(at);
    void c.setLookAt(...shot.position, ...shot.target, smooth);
  });

  return (
    <CameraControls
      ref={ref}
      makeDefault
      minDistance={80}
      maxDistance={16000}
      maxPolarAngle={(84 * Math.PI) / 180}
      dollySpeed={0.6}
    />
  );
}
import { Bloom, EffectComposer, Vignette } from "@react-three/postprocessing";

import { useThrottledStore } from "../lib/useThrottledStore";
import { effectsOn, uiStore } from "../state/uiStore";

/** Bloom (mipmap blur, threshold about 0.2) and a light vignette; off in reduce motion and when
 * the frame rate degrades (§17.3, §17.11). No film grain in phase 7. */
export function Effects() {
  const on = useThrottledStore(uiStore, effectsOn, 4);
  if (!on) return null;
  return (
    <EffectComposer multisampling={0}>
