// Camera shots for the theater presets (§17.3). Scene meters; see sceneMath for the frame.
import type { CameraPreset } from "../state/uiStore";
import { bearingVector, type Vec3 } from "./sceneMath";

export interface Shot {
  position: Vec3;
  target: Vec3;
}

/** Overview: the fence, the 3.5 km radar ring and the core, seen from the south. */
export const OVERVIEW: Shot = { position: [300, 3100, 4500], target: [300, 0, 450] };

/** Static presets; follow and target depend on the live data. */
export const PRESETS: Record<Exclude<CameraPreset, "follow" | "target">, Shot> = {
  overview: OVERVIEW,
  memory: { position: [0, 9000, 11000], target: [0, 0, 0] }, // phase 8: frames the ghosts
  swarm: OVERVIEW, // phase 9
};

export const FOLLOW_BACK_M = 400;
export const FOLLOW_UP_M = 180;
export const TARGET_M = 900;

/** Chase shot: 400 m behind the drone along its heading, a little above. */
export function followShot(drone: Vec3, headingDeg: number | null): Shot {
  const d = bearingVector(headingDeg ?? 0);
  return {
    position: [
      drone[0] - FOLLOW_BACK_M * d[0],
      drone[1] + FOLLOW_UP_M,
      drone[2] - FOLLOW_BACK_M * d[2],
    ],
    target: drone,
  };
}

/** Target shot: 900 m from the target asset, from the south at about 35° elevation. */
export function targetShot(at: Vec3): Shot {
  const el = (35 * Math.PI) / 180;
  return {
    position: [at[0], TARGET_M * Math.sin(el), at[2] + TARGET_M * Math.cos(el)],
    target: [at[0], 0, at[2]],
  };
}
import { CameraControls } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useEffect, useRef } from "react";

import type { Scene } from "../api/messages";
import { useThrottledStore } from "../lib/useThrottledStore";
import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import { followShot, PRESETS, targetShot } from "./camera";
import { toScene, type Origin, type Vec3 } from "./sceneMath";

/**
 * Camera presets with 1.2 s damped transitions (instant in reduce motion) and free orbit
 * otherwise (§17.3). Follow tracks the latest real detection; target frames the identified asset.
 */
export function CameraRig({ scene, origin }: { scene: Scene | null; origin: Origin | null }) {
  const ref = useRef<CameraControls>(null);
  const aimed = useRef<string | null>(null);
  const first = useRef(true);
  const preset = useThrottledStore(uiStore, (s) => s.camera, 10);

  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    c.smoothTime = 0.35; // ≈ 1.2 s to settle
    const smooth = !first.current && !reduceMotion(uiStore.getState());
    first.current = false;
    aimed.current = null;
    if (preset === "follow" || preset === "target") return; // from the live data, below
    const s = PRESETS[preset];
    void c.setLookAt(...s.position, ...s.target, smooth);
  }, [preset]);

  useFrame(() => {
    const c = ref.current;
    if (!c || !origin || (preset !== "follow" && preset !== "target")) return;
    const s = replayStore.getState();
    const smooth = !reduceMotion(uiStore.getState());
    const f = s.features[s.features.length - 1];
    if (preset === "follow") {
      const id = s.hello?.tracks[0];
      const pts = id ? s.tracks[id] : undefined;
      const last = pts?.[pts.length - 1];
      if (!last) return;
      const shot = followShot(toScene(last.x, last.y, last.alt, origin), f?.heading_deg ?? null);
      void c.setLookAt(...shot.position, ...shot.target, smooth);
      return;
    }
    const asset = scene?.assets.find((a) => a.asset_id === f?.target_asset_id);
    const at = asset
      ? toScene(asset.centroid_x_m, asset.centroid_y_m, 0, origin)
      : ([0, 0, 0] as Vec3);
    const shot = targetShot(at);
    void c.setLookAt(...shot.position, ...shot.target, smooth);
  });

  return (
    <CameraControls
      ref={ref}
      makeDefault
      minDistance={80}
      maxDistance={16000}
      maxPolarAngle={(84 * Math.PI) / 180}
      dollySpeed={0.6}
    />
  );
}
