// Pure helpers for the live theater (SPEC §17.3, D-109). Scene frame: 1 unit = 1 m, origin =
// installation origin, x_m → x (east), y_m → −z (north is −z), altitude → y. No rotation.
// Bearings are degrees clockwise from north in [0, 360).

export type Vec3 = [number, number, number];
export type Vec2 = [number, number];

export interface Origin {
  x: number;
  y: number;
}

/** Region meters (and altitude) to scene coordinates. */
export function toScene(x_m: number, y_m: number, alt: number, origin: Origin): Vec3 {
  return [x_m - origin.x, alt, -(y_m - origin.y)];
}

export function wrap360(deg: number): number {
  return ((deg % 360) + 360) % 360;
}

/** Bearing from one region-frame point to another (clockwise from north). */
export function bearingDeg(from: Vec2, to: Vec2): number {
  const dx = to[0] - from[0];
  const dy = to[1] - from[1];
  return wrap360((Math.atan2(dx, dy) * 180) / Math.PI);
}

/** A horizontal unit vector in scene space along a bearing. */
export function bearingVector(deg: number): Vec3 {
  const r = (deg * Math.PI) / 180;
  return [Math.sin(r), 0, -Math.cos(r)];
}

/** three.js rotation about +y that points the local −z axis along a bearing. */
export function bearingToYaw(deg: number): number {
  return (-deg * Math.PI) / 180;
}

/**
 * Radar sweep angle (§17.3): the bearing of the last detection, advanced 360° × rate per second
 * of replay time since it. The beam crosses the drone at each real detection and stands still
 * while the replay is paused (the clock does not move).
 */
export function sweepAngleDeg(
  detBearing: number,
  rateHz: number,
  clock: number,
  detT: number,
): number {
  return wrap360(detBearing + 360 * rateHz * Math.max(0, clock - detT));
}

/** A point on a quadratic arc from a to b that rises `lift` meters above the chord at its middle. */
export function arcPoint(a: Vec3, b: Vec3, t: number, lift: number): Vec3 {
  const u = Math.min(Math.max(t, 0), 1);
  const c: Vec3 = [(a[0] + b[0]) / 2, Math.max(a[1], b[1]) + lift, (a[2] + b[2]) / 2];
  const w0 = (1 - u) * (1 - u);
  const w1 = 2 * (1 - u) * u;
  const w2 = u * u;
  return [
    w0 * a[0] + w1 * c[0] + w2 * b[0],
    w0 * a[1] + w1 * c[1] + w2 * b[1],
    w0 * a[2] + w1 * c[2] + w2 * b[2],
  ];
}

export const PACKET_LEG1_S = 0.9; // detection → detecting sensor
export const PACKET_LEG2_S = 0.6; // sensor → Kairos core

/** Where a data packet is `age` wall seconds after its detection; null once it has arrived. */
export function packetPosition(from: Vec3, sensor: Vec3, core: Vec3, age: number): Vec3 | null {
  if (age < 0 || age > PACKET_LEG1_S + PACKET_LEG2_S) return null;
  if (age <= PACKET_LEG1_S) {
    const lift = 0.15 * Math.hypot(sensor[0] - from[0], sensor[2] - from[2]);
    return arcPoint(from, sensor, age / PACKET_LEG1_S, lift);
  }
  const lift = 0.2 * Math.hypot(core[0] - sensor[0], core[2] - sensor[2]);
  return arcPoint(sensor, core, (age - PACKET_LEG1_S) / PACKET_LEG2_S, lift);
}

export const TRAIL_S = 60;

/** Phosphor trail: 1 at the newest point, 0 for points 60 replay seconds old. */
export function trailAlpha(age_s: number): number {
  return Math.min(1, Math.max(0, 1 - age_s / TRAIL_S));
}

export const RF_RING_M = 300;
export const RF_RING_S = 1.2;

/** RF ring radius: 0 → 300 m over 1.2 s after the detection (null outside that window). */
export function rfRingRadius(age_s: number): number | null {
  if (age_s < 0 || age_s > RF_RING_S) return null;
  return (RF_RING_M * age_s) / RF_RING_S;
}

/** The unknown-track quatrefoil frame (MIL-STD-2525 inspired): four lobes, unit size. */
export function quatrefoil(n = 96, r = 1): Vec2[] {
  const out: Vec2[] = [];
  for (let i = 0; i <= n; i++) {
    const th = (i / n) * 2 * Math.PI;
    const rad = r * (0.72 + 0.28 * Math.cos(4 * th));
    out.push([rad * Math.sin(th), rad * Math.cos(th)]);
  }
  return out;
}

/** World size that appears `px` pixels tall at distance `dist` (perspective camera). */
export function screenScale(dist: number, fovDeg: number, viewportPx: number, px: number): number {
  const h = 2 * dist * Math.tan((fovDeg * Math.PI) / 360);
  return (h * px) / Math.max(1, viewportPx);
}

/** Hatch segments (region meters) inside a polygon: parallel lines `spacing` apart at `angleDeg`. */
export function hatchSegments(poly: Vec2[], spacing: number, angleDeg = 45): [Vec2, Vec2][] {
  if (poly.length < 3) return [];
  const a = (angleDeg * Math.PI) / 180;
  const [c, s] = [Math.cos(a), Math.sin(a)];
  // rotate into a frame where hatch lines are horizontal: v = −x·s + y·c
  const rot = poly.map(([x, y]) => [x * c + y * s, -x * s + y * c] as Vec2);
  const vs = rot.map((p) => p[1]);
  const out: [Vec2, Vec2][] = [];
  const lo = Math.ceil(Math.min(...vs) / spacing) * spacing;
  for (let v = lo; v <= Math.max(...vs); v += spacing) {
    const xs: number[] = [];
    for (let i = 0; i < rot.length; i++) {
      const p = rot[i] as Vec2;
      const q = rot[(i + 1) % rot.length] as Vec2;
      if (p[1] === q[1] || v < Math.min(p[1], q[1]) || v >= Math.max(p[1], q[1])) continue;
      xs.push(p[0] + ((v - p[1]) / (q[1] - p[1])) * (q[0] - p[0]));
    }
    xs.sort((m, n) => m - n);
    for (let i = 0; i + 1 < xs.length; i += 2) {
      const u0 = xs[i] as number;
      const u1 = xs[i + 1] as number;
      out.push([
        [u0 * c - v * s, u0 * s + v * c],
        [u1 * c - v * s, u1 * s + v * c],
      ]);
    }
  }
  return out;
}

/** The mean of a ring's vertices (the closing vertex counted once). */
export function ringCenter(poly: Vec2[]): Vec2 {
  const pts = poly.length > 1 && poly[0]?.[0] === poly.at(-1)?.[0] ? poly.slice(0, -1) : poly;
  const n = Math.max(1, pts.length);
  return [pts.reduce((a, p) => a + p[0], 0) / n, pts.reduce((a, p) => a + p[1], 0) / n];
}

/** The Kairos core: 2.4 km south-east of the origin, 120 m up (D-112). */
export const CORE_POSITION: Vec3 = [2400 * Math.SQRT1_2, 120, 2400 * Math.SQRT1_2];

/** Asset heights by kind, meters (presentation constants, §17.3: 6–20 m). */
export const ASSET_HEIGHT_M: Record<string, number> = {
  hq: 20,
  housing: 9,
  fuel_farm: 12,
  flight_line: 6,
  munitions: 8,
};

export function assetLabel(kind: string): string {
  if (kind === "hq") return "HQ";
  const s = kind.replace(/_/g, " ");
  return s.charAt(0).toUpperCase() + s.slice(1);
}
// Small geometry builders shared by the theater components.
import {
  AdditiveBlending,
  BufferGeometry,
  Float32BufferAttribute,
  MeshBasicMaterial,
  RingGeometry,
} from "three";

import { color } from "./palette";

/** A horizontal circle (xz plane) of radius `r` as a line strip. */
export function circleLine(r: number, n = 128, y = 0): BufferGeometry {
  const pts: number[] = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(r * Math.cos(a), y, r * Math.sin(a));
  }
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(pts, 3));
  return g;
}

/**
 * A flat sector (xz plane) from bearing 0 back to −`widthDeg` (it trails a clockwise beam whose
 * leading edge points along local −z), with RGBA vertex colors fading to transparent behind.
 */
export function sweepWedge(radius: number, widthDeg: number, n = 24, alpha = 0.32): BufferGeometry {
  const pos: number[] = [];
  const col: number[] = [];
  const c = color("--flash");
  for (let i = 0; i < n; i++) {
    const b0 = (-(i / n) * widthDeg * Math.PI) / 180;
    const b1 = (-((i + 1) / n) * widthDeg * Math.PI) / 180;
    const a0 = alpha * (1 - i / n);
    const a1 = alpha * (1 - (i + 1) / n);
    pos.push(
      0,
      0,
      0,
      radius * Math.sin(b1),
      0,
      -radius * Math.cos(b1),
      radius * Math.sin(b0),
      0,
      -radius * Math.cos(b0),
    );
    col.push(c.r, c.g, c.b, a0 * 0.4, c.r, c.g, c.b, a1, c.r, c.g, c.b, a0);
  }
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(pos, 3));
  g.setAttribute("color", new Float32BufferAttribute(col, 4));
  return g;
}

/** A thin flat unit ring (xz plane) to scale to any radius. */
export function unitRing(inner = 0.965): RingGeometry {
  const g = new RingGeometry(inner, 1, 96);
  g.rotateX(-Math.PI / 2);
  return g;
}

export function glowMaterial(
  name: "--flash" | "--afterglow" | "--alert",
  opacity = 1,
): MeshBasicMaterial {
  return new MeshBasicMaterial({
    color: color(name),
    transparent: true,
    opacity,
    blending: AdditiveBlending,
    depthWrite: false,
  });
}
import { Billboard, Text } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import { type Group, MeshBasicMaterial, type PerspectiveCamera, Vector3 } from "three";

import { FONT_UI } from "../theme/fontFiles";
import { color } from "./palette";
import { screenScale, type Vec3 } from "./sceneMath";

const tmp = new Vector3();

/**
 * The base material every label derives from. troika derives its text (and outline) materials
 * from the base by prototype, so depth settings must live here: a `material-depthTest` prop only
 * reaches the fill, and the labels were then cut by the grid and the asset boxes.
 */
const LABEL_BASE = new MeshBasicMaterial({
  transparent: true,
  depthTest: false,
  depthWrite: false,
  toneMapped: false,
});

type Tone =
  "--ink-hi" | "--ink-mid" | "--ink-low" | "--flash" | "--afterglow" | "--bone" | "--alert";

/**
 * A label that faces the camera and keeps a constant size on screen (`px` tall), in B612 from our
 * own origin (troika would otherwise fetch a CDN font, rule 5).
 */
export function Label(props: {
  text: string;
  position: Vec3;
  px?: number;
  tone?: Tone;
  anchorX?: "left" | "center" | "right";
  anchorY?: "top" | "middle" | "bottom";
  opacity?: number;
  /** Screen offset of the text from the anchor point, pixels (positive is up). */
  dyPx?: number;
  /** Screen offset to the right, pixels. */
  dxPx?: number;
}) {
  const ref = useRef<Group>(null);
  const px = props.px ?? 13;
  useFrame(({ camera, size }) => {
    const g = ref.current;
    if (!g) return;
    const d = camera.position.distanceTo(g.getWorldPosition(tmp));
    g.scale.setScalar(screenScale(d, (camera as PerspectiveCamera).fov ?? 45, size.height, px));
  });
  return (
    <Billboard ref={ref} position={props.position}>
      <Text
        position={[(props.dxPx ?? 0) / px, (props.dyPx ?? 0) / px, 0]}
        font={FONT_UI}
        fontSize={1}
        anchorX={props.anchorX ?? "center"}
        anchorY={props.anchorY ?? "bottom"}
        color={color(props.tone ?? "--ink-mid")}
        fillOpacity={props.opacity ?? 1}
        outlineWidth={0.08}
        outlineColor={color("--scope")}
        outlineOpacity={0.85}
        renderOrder={10}
        material={LABEL_BASE}
      >
        {props.text}
      </Text>
    </Billboard>
  );
}
import { Edges } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import { AdditiveBlending, type Group, type Mesh, type MeshBasicMaterial } from "three";

import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import { Label } from "./Label";
import { color } from "./palette";
import { CORE_POSITION } from "./sceneMath";

const DEG_PER_INGEST = 4;
const PULSE_MS = 450;

/**
 * The Kairos core (§17.3, D-012): a ringed octahedron that turns a few degrees with each real
 * `ingest` batch and pulses when it arrives. When nothing is written, it is perfectly still.
 */
export function Core() {
  const spin = useRef<Group>(null);
  const glow = useRef<Mesh>(null);
  const shown = useRef(0);
  useFrame((_, dt) => {
    const s = replayStore.getState();
    const target = (s.ingestCount * DEG_PER_INGEST * Math.PI) / 180;
    const reduce = reduceMotion(uiStore.getState());
    shown.current = reduce
      ? target
      : shown.current + (target - shown.current) * (1 - Math.exp(-dt / 0.2));
    if (spin.current) spin.current.rotation.y = shown.current;
    const g = glow.current;
    if (g) {
      const age = performance.now() - s.ingestWall;
      const p = s.ingestCount > 0 ? Math.exp(-Math.max(0, age) / PULSE_MS) : 0;
      (g.material as MeshBasicMaterial).opacity = 0.06 + 0.45 * p;
      g.scale.setScalar(70 * (1 + (reduce ? 0 : 0.25 * p)));
    }
  });
  const flash = color("--flash");
  return (
    <group position={CORE_POSITION}>
      <group ref={spin}>
        <mesh>
          <octahedronGeometry args={[70, 0]} />
          <meshBasicMaterial color={flash} transparent opacity={0.08} depthWrite={false} />
          <Edges color={flash} lineWidth={1.2} />
        </mesh>
        <mesh rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[110, 1.2, 6, 96]} />
          <meshBasicMaterial color={flash} transparent opacity={0.7} />
        </mesh>
        <mesh rotation={[Math.PI / 2.6, 0.4, 0]}>
          <torusGeometry args={[140, 0.9, 6, 96]} />
          <meshBasicMaterial color={flash} transparent opacity={0.45} />
        </mesh>
      </group>
      <mesh ref={glow}>
        <sphereGeometry args={[1, 24, 16]} />
        <meshBasicMaterial
          color={flash}
          transparent
          opacity={0.06}
          blending={AdditiveBlending}
          depthWrite={false}
        />
      </mesh>
      <Label
        text="Kairos core: DuckDB and LanceDB"
        position={[0, -95, 0]}
        px={13}
        tone="--ink-hi"
        anchorY="top"
      />
    </group>
  );
}
import { Billboard } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import { memo, useMemo, useRef } from "react";
import {
  AdditiveBlending,
  BufferGeometry,
  DynamicDrawUsage,
  Float32BufferAttribute,
  type Group,
  Line,
  LineBasicMaterial,
  LineLoop,
  type Mesh,
  Vector3,
} from "three";

import { clockNow, replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import { unitRing } from "./geom";
import { Label } from "./Label";
import { color } from "./palette";
import {
  bearingDeg,
  bearingToYaw,
  quatrefoil,
  screenScale,
  toScene,
  TRAIL_S,
  trailAlpha,
  type Origin,
} from "./sceneMath";

const TRAIL_MAX = 256;
const RID_QUIET_S = 10; // "No Remote ID" when nothing was heard for 10 replay seconds
const GLYPH_PX = 22;
const tmp = new Vector3();

function makeLine(points: number[], name: "--flash" | "--alert", opacity = 1, loop = false) {
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(points, 3));
  const m = new LineBasicMaterial({
    color: color(name),
    transparent: true,
    opacity,
    depthWrite: false,
  });
  return loop ? new LineLoop(g, m) : new Line(g, m);
}

/**
 * One live track (§17.3): a constant-screen-size quatrefoil with a heading tick at the latest
 * radar detection, a drop line, a ground ring and a 60 s phosphor trail fading from flash blue to
 * transparent. Every position is a real detection; the glyph eases over ~0.1 s between them.
 */
export const Drone = memo(function Drone({ trackId, origin }: { trackId: string; origin: Origin }) {
  const glyph = useMemo(() => {
    const pts = quatrefoil(96, 0.5).flatMap(([x, y]) => [x, y, 0]);
    return makeLine(pts, "--flash", 1, true);
  }, []);
  const tick = useMemo(() => makeLine([0, 0, 0, 0, 0, -1], "--flash"), []);
  const drop = useMemo(() => makeLine([0, 0, 0, 0, 0, 0], "--flash", 0.45), []);
  const trail = useMemo(() => {
    const g = new BufferGeometry();
    const pos = new Float32BufferAttribute(new Float32Array(TRAIL_MAX * 3), 3);
    const col = new Float32BufferAttribute(new Float32Array(TRAIL_MAX * 4), 4);
    pos.setUsage(DynamicDrawUsage);
    col.setUsage(DynamicDrawUsage);
    g.setAttribute("position", pos);
    g.setAttribute("color", col);
    g.setDrawRange(0, 0);
    const m = new LineBasicMaterial({
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      blending: AdditiveBlending,
    });
    return new Line(g, m);
  }, []);
  const ringGeom = useMemo(() => unitRing(0.86), []);
  const body = useRef<Group>(null);
  const icon = useRef<Group>(null);
  const ring = useRef<Mesh>(null);
  const tag = useRef<Group>(null);
  const shown = useRef<Vector3 | null>(null);

  useFrame(({ camera, size }, dt) => {
    const s = replayStore.getState();
    const pts = s.tracks[trackId];
    const last = pts?.[pts.length - 1];
    const b = body.current;
    if (!b) return;
    b.visible = last !== undefined;
    if (!pts || !last) return;
    const t = clockNow(s);
    const target = new Vector3(...toScene(last.x, last.y, last.alt, origin));
    const reduce = reduceMotion(uiStore.getState());
    if (!shown.current || reduce) shown.current = target.clone();
    else shown.current.lerp(target, 1 - Math.exp(-dt / 0.1));
    const p = shown.current;
    b.position.copy(p);
    const k = screenScale(
      camera.position.distanceTo(b.getWorldPosition(tmp)),
      45,
      size.height,
      GLYPH_PX,
    );
    icon.current?.scale.setScalar(k);
    // heading: the latest feature row of this track, else the last two detections
    const f = s.features[s.features.length - 1];
    const prev = pts[pts.length - 2];
    const hdg =
      f && f.track_id === trackId && f.heading_deg !== null
        ? f.heading_deg
        : prev
          ? bearingDeg([prev.x, prev.y], [last.x, last.y])
          : null;
    tick.visible = hdg !== null;
    if (hdg !== null) {
      tick.rotation.y = bearingToYaw(hdg);
      tick.scale.setScalar(k * 1.1);
    }
    const dpos = drop.geometry.getAttribute("position");
    dpos.setXYZ(1, 0, -p.y, 0);
    dpos.needsUpdate = true;
    if (ring.current) {
      ring.current.position.set(0, -p.y + 0.6, 0);
      ring.current.scale.setScalar(k * 0.45);
    }
    // phosphor trail: the last 60 replay seconds, alpha 1 → 0
    const pa = trail.geometry.getAttribute("position");
    const ca = trail.geometry.getAttribute("color");
    const c = color("--flash");
    let n = 0;
    for (let i = Math.max(0, pts.length - TRAIL_MAX); i < pts.length; i++) {
      const q = pts[i];
      if (!q || t - q.t_s > TRAIL_S || q.t_s > t) continue;
      const [x, y, z] = toScene(q.x, q.y, q.alt, origin);
      pa.setXYZ(n, x - p.x, y - p.y, z - p.z);
      ca.setXYZW(n, c.r, c.g, c.b, trailAlpha(t - q.t_s));
      n++;
    }
    pa.needsUpdate = true;
    ca.needsUpdate = true;
    trail.geometry.setDrawRange(0, n);
    const quiet = !s.rid.some((r) => t - r.t_s >= 0 && t - r.t_s <= RID_QUIET_S);
    if (tag.current) tag.current.visible = quiet;
  });

  return (
    <group ref={body} visible={false}>
      <primitive object={trail} />
      <primitive object={drop} />
      <primitive object={tick} />
      <mesh ref={ring} geometry={ringGeom}>
        <meshBasicMaterial color={color("--flash")} transparent opacity={0.5} depthWrite={false} />
      </mesh>
      <Billboard>
        <group ref={icon}>
          <primitive object={glyph} />
        </group>
      </Billboard>
      <group ref={tag}>
        <Label
          text="No Remote ID"
          position={[0, 0, 0]}
          px={12}
          tone="--alert"
          anchorX="center"
          anchorY="bottom"
          dyPx={16}
        />
      </group>
    </group>
  );
});

