        EvidenceError,
        export_evidence,
        passed,
        signer_for,
        verify_evidence,
    )

    if not body.approve:
        raise HTTPException(400, "approval required (rule 8): an export needs an explicit human "
                                 "approval; send approve: true. Nothing was written.")  # fmt: skip
    try:
