import { afterEach } from "vitest";

afterEach(() => cleanup());
// Shared setup for the panel tests: fresh stores, the throttle wait, canvas and dialog stubs.
import { act } from "@testing-library/react";
import { vi } from "vitest";

import { caseStore } from "../src/state/caseStore";
import { matchStore } from "../src/state/matchStore";
import { replayStore } from "../src/state/replayStore";
import { uiStore } from "../src/state/uiStore";

export function resetStores(): void {
  replayStore.getState().reset();
  matchStore.setState({
    match: null,
    forecast: null,
    recall: null,
    dtw: null,
    entrance: 0,
    top3: "",
    decisions: {},
    busy: {},
    error: null,
  });
  caseStore.getState().reset();
  uiStore.setState({ userReduce: true, osReduce: false });
}

/** Let the 10 Hz throttle flush (and pending promises settle). */
export function flush(ms = 130) {
  return act(async () => {
    await new Promise((r) => setTimeout(r, ms));
  });
}

export function stubCanvas(): ReturnType<typeof vi.fn> {
  const calls = vi.fn();
  const ctx = new Proxy(
    {},
    {
      get: (_t, prop) => {
        if (prop === "createLinearGradient") return () => ({ addColorStop: () => undefined });
        return (...args: unknown[]) => calls(prop, ...args);
      },
      set: () => true,
    },
  );
  vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
    ctx as unknown as CanvasRenderingContext2D,
  );
  return calls;
}

export function stubDialog(): void {
  const proto = HTMLDialogElement.prototype as unknown as Record<string, unknown>;
  proto.showModal = function (this: HTMLDialogElement) {
    this.setAttribute("open", "");
  };
  proto.close = function (this: HTMLDialogElement) {
    this.removeAttribute("open");
    this.dispatchEvent(new Event("close"));
  };
}

/** xs[i], or a test failure (no non-null assertions). */
export function nth<T>(xs: T[], i: number): T {
  const v = xs[i];
  if (v === undefined) throw new Error(`no element ${i} (of ${xs.length})`);
  return v;
}
import { expect, type APIRequestContext, type Locator, type Page } from "@playwright/test";

export const INCIDENT = "DEMO-BRAVO-0828";
export const FIGURES = "../reports/figures/ui";

/** A clean ledger (seed head) and empty live tables on the e2e server. */
export async function reseed(request: APIRequestContext): Promise<number> {
  const r = await request.post("/api/admin/reseed");
  expect(r.ok()).toBeTruthy();
  expect((await request.post("/api/admin/reset")).ok()).toBeTruthy();
  return ((await r.json()) as { head_seq: number }).head_seq;
}

export async function openLive(page: Page): Promise<void> {
  await page.goto(`/live/${INCIDENT}`);
  await expect(page.getByTestId("replay-status")).toHaveText(/Paused|Live/);
}

export async function play(page: Page, speed: 1 | 2 | 5 = 5): Promise<void> {
  await page.getByRole("button", { name: `Speed ${speed} times` }).click();
  await page.getByRole("button", { name: "Play" }).click();
  await expect(page.getByTestId("replay-status")).toHaveText("Live");
}

/** Change the speed only (Play is disabled while playing). */
export async function speed(page: Page, value: 1 | 2 | 5): Promise<void> {
  const b = page.getByRole("button", { name: `Speed ${value} times` });
  await b.click();
  await expect(b).toHaveAttribute("aria-pressed", "true");
}

export async function pause(page: Page): Promise<void> {
  await page.getByRole("button", { name: "Pause" }).click();
  await expect(page.getByTestId("replay-status")).toHaveText("Paused");
}

/** Seconds on the command bar's replay clock (T+mm:ss). */
export async function clockSeconds(page: Page): Promise<number> {
  const t = (await page.getByTestId("replay-clock").textContent()) ?? "";
  const m = /T\+(\d+):(\d+)/.exec(t);
  return m ? Number(m[1]) * 60 + Number(m[2]) : -1;
}

export async function waitForClock(page: Page, seconds: number, timeoutMs = 90_000) {
  await expect
    .poll(() => clockSeconds(page), { timeout: timeoutMs, intervals: [100] })
    .toBeGreaterThanOrEqual(seconds);
}

export async function numberIn(l: Locator): Promise<number> {
  const t = (await l.textContent()) ?? "";
  const m = /[\d,]+(\.\d+)?/.exec(t);
  return m ? Number(m[0].replaceAll(",", "")) : Number.NaN;
}

export async function headSeq(request: APIRequestContext): Promise<number> {
  const v = (await (await request.get("/api/ledger/verify")).json()) as { head_seq: number };
  return v.head_seq;
}
// SPEC §17.12: every route renders the command bar; axe finds no serious or critical violation;
// at 1440 × 900 nothing scrolls sideways and both rails show; below 1280 px the rails stack.
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";

import { INCIDENT, openLive, reseed } from "./helpers";

const ROUTES = [
  `/live/${INCIDENT}`,
  "/explainer",
  "/cases",
  "/swarm",
  "/evidence",
  "/delta",
  "/eval",
];

for (const route of ROUTES) {
  test(`axe and the command bar on ${route}`, async ({ page, request }) => {
    if (route.startsWith("/live")) {
      await reseed(request);
      await openLive(page);
    } else {
      await page.goto(route);
    }
    await expect(page.getByRole("navigation", { name: "Breadcrumb" })).toContainText(
      "Kairos Defense",
    );
    const res = await new AxeBuilder({ page }).exclude("canvas").analyze();
    const bad = res.violations.filter((v) => v.impact === "serious" || v.impact === "critical");
    expect(bad.map((v) => `${v.id}: ${v.nodes.map((n) => n.target.join(" ")).join(", ")}`)).toEqual(
      [],
    );
  });
}

test("the root opens Live watch for the live incident", async ({ page }) => {
  await page.goto("/");
  await expect(page).toHaveURL(new RegExp(`/live/${INCIDENT}$`));
});

test("layout holds at 1440 x 900", async ({ page, request }) => {
  await reseed(request);
  await page.setViewportSize({ width: 1440, height: 900 });
  await openLive(page);
  const sideways = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  expect(sideways).toBe(false);
  for (const name of ["Memory rail", "Instrument rail", "Live theater"]) {
    await expect(page.getByLabel(name, { exact: true })).toBeInViewport();
  }
});

test("rails stack under the theater below 1280 px", async ({ page, request }) => {
  await reseed(request);
  await page.setViewportSize({ width: 1200, height: 900 });
  await openLive(page);
  const theater = await page.getByLabel("Live theater", { exact: true }).boundingBox();
  const memory = await page.getByLabel("Memory rail", { exact: true }).boundingBox();
  const instruments = await page.getByLabel("Instrument rail", { exact: true }).boundingBox();
  if (!theater || !memory || !instruments) throw new Error("a region is not rendered");
  expect(memory.y).toBeGreaterThanOrEqual(theater.y + theater.height - 1);
  expect(instruments.y).toBeGreaterThanOrEqual(memory.y + memory.height - 1);
  const sideways = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  expect(sideways).toBe(false);
});

test("shortcuts dialog lists M and closes with Escape", async ({ page }) => {
  await page.goto("/cases");
  await expect(page.getByRole("heading", { name: "Case board" })).toBeVisible();
  await page.locator("body").press("?");
  const dialog = page.getByRole("dialog", { name: "Keyboard shortcuts" });
  await expect(dialog).toBeVisible();
  await expect(dialog).toContainText("Reduce motion");
  await page.keyboard.press("Escape");
  await expect(dialog).toBeHidden();
});
// SPEC §17.13: screenshots at the phase 7 moments (D-113: first contact, T+45, T+90, after an
// approval; Director beats arrive in phase 8), at 1920 × 1080 and 1440 × 900.
import { mkdirSync } from "node:fs";

import { expect, test, type Page } from "@playwright/test";

import { FIGURES, openLive, pause, play, reseed, waitForClock } from "./helpers";

mkdirSync(FIGURES, { recursive: true });

async function shot(page: Page, moment: string, w: number, h: number) {
  await page.waitForTimeout(1500); // let 1.2 s fades and the 10 Hz panels settle
  await page.screenshot({ path: `${FIGURES}/phase07-${moment}-${w}x${h}.png` });
}

for (const [w, h] of [
  [1920, 1080],
  [1440, 900],
] as const) {
  test(`screenshots at ${w}x${h}`, async ({ page, request }) => {
    await reseed(request);
    await page.setViewportSize({ width: w, height: h });
    await openLive(page);
    await play(page, 2);
    await waitForClock(page, 4);
    await pause(page);
    await shot(page, "first-contact", w, h);
    await play(page, 5);
    await waitForClock(page, 46);
    await pause(page);
    await shot(page, "t045", w, h);
    await play(page, 5);
    await waitForClock(page, 91);
    await pause(page);
    await expect(page.getByTestId("match-entry")).toHaveCount(3);
    await shot(page, "t090", w, h);
    const approve = page
      .getByRole("button", { name: /^Approve link/ })
      .and(page.locator(":enabled"));
    await approve.first().click();
    await expect(page.locator('[data-testid="score-ring"][data-state="approved"]')).toHaveCount(1);
    await shot(page, "approved", w, h);
  });
}
// SPEC §20 phase 7 exit check: the median frame rate and the machine it was measured on
// (recorded, not asserted: phase 8 owns >= 50 fps). Written to reports/figures/ui/perf.json.
import { mkdirSync, writeFileSync } from "node:fs";
import os from "node:os";

import { expect, test } from "@playwright/test";

import { FIGURES, openLive, play, reseed, speed, waitForClock } from "./helpers";

test("frame rate over 10 s of 1x playback", async ({ page, request, browserName }) => {
  await reseed(request);
  await page.setViewportSize({ width: 1920, height: 1080 });
  await openLive(page);
  await play(page, 5);
  await waitForClock(page, 5);
  await speed(page, 1);
  const frames = await page.evaluate(
    () =>
      new Promise<number[]>((resolve) => {
        const ts: number[] = [];
        const t0 = performance.now();
        const step = (t: number) => {
          ts.push(t);
          if (t - t0 < 10_000) requestAnimationFrame(step);
          else resolve(ts);
        };
        requestAnimationFrame(step);
      }),
  );
  const dts = frames
    .slice(1)
    .map((t, i) => t - (frames[i] ?? t))
    .sort((a, b) => a - b);
  const q = (p: number) => dts[Math.min(dts.length - 1, Math.floor(p * dts.length))] ?? Number.NaN;
  const gl = await page.evaluate(() => {
    const c = document.createElement("canvas").getContext("webgl2");
    if (!c) return { renderer: "no WebGL2", vendor: "" };
    const ext = c.getExtension("WEBGL_debug_renderer_info");
    return {
      renderer: String(
        ext ? c.getParameter(ext.UNMASKED_RENDERER_WEBGL) : c.getParameter(c.RENDERER),
      ),
      vendor: String(ext ? c.getParameter(ext.UNMASKED_VENDOR_WEBGL) : c.getParameter(c.VENDOR)),
    };
  });
  const perf = await page.getByTestId("theater").getAttribute("data-perf");
  const out = {
    measured_at: new Date().toISOString(),
    seconds: 10,
    frames: frames.length,
    fps_median: Math.round((1000 / q(0.5)) * 10) / 10,
    fps_p5: Math.round((1000 / q(0.95)) * 10) / 10,
    frame_ms_p50: Math.round(q(0.5) * 100) / 100,
    frame_ms_p95: Math.round(q(0.95) * 100) / 100,
    viewport: "1920x1080",
    browser: `${browserName} ${page.context().browser()?.version() ?? ""}`,
    user_agent: await page.evaluate(() => navigator.userAgent),
    webgl: gl,
    theater_perf_level: perf,
    cpu: os.cpus()[0]?.model ?? "unknown",
    cores: os.cpus().length,
    platform: `${os.platform()} ${os.release()}`,
    memory_gb: Math.round(os.totalmem() / 2 ** 30),
  };
  mkdirSync(FIGURES, { recursive: true });
  writeFileSync(`${FIGURES}/perf.json`, JSON.stringify(out, null, 1) + "\n");
  expect(out.frames).toBeGreaterThan(10);
});
// Typed stream messages for tests (shapes from the generated OpenAPI types).
import type {
  ClockMsg,
  FeaturesMsg,
  HelloMsg,
  IngestMsg,
  LedgerMsg,
  MatchItem,
  MatchMsg,
  PointMsg,
  RfMsg,
} from "../src/api/messages";

export const HELLO: HelloMsg = {
  type: "hello",
  incident_id: "DEMO-BRAVO-0828",
  installation_id: "BRAVO",
  region_id: "COASTAL",
  start_ts: "2026-08-29T02:40:06.000Z",
  duration_s: 515,
  speed: 1,
  playing: false,
  tracks: ["DEMO-BRAVO-0828-T1"],
  is_swarm: false,
  matching: true,
  min_track_s: 45,
  rerun_every_s: 5,
  utc_offset_hours: -5,
};

export function clock(t_s: number, playing = true, speed = 1, seeked = false): ClockMsg {
  return { type: "clock", t_s, ts: "2026-08-29T02:41:08.000Z", speed, playing, seeked };
}

export function point(t_s: number, x = 21680, y = -4880, alt = 90): PointMsg {
  return {
    type: "point",
    incident_id: "DEMO-BRAVO-0828",
    track_id: "DEMO-BRAVO-0828-T1",
    sensor_id: "BRAVO-RADAR-1",
    t_s,
    x_m: x,
    y_m: y,
    alt_m: alt,
    quality: 0.88,
  };
}

export function rf(t_s: number, bearing = 335): RfMsg {
