import { baseName, localDate } from "../lib/format";
import { useThrottledStore } from "../lib/useThrottledStore";
import { useThrottledStores } from "../lib/useThrottledStores";
import { directorStore } from "../state/directorStore";
import { ghostStore, readyPath } from "../state/ghostStore";
import { matchStore } from "../state/matchStore";
import { replayStore } from "../state/replayStore";
import { reduceMotion, uiStore } from "../state/uiStore";
import type { StoreApi } from "zustand/vanilla";
import { dissolveAlpha, isFenceTarget, mapGhost, type GhostPoint } from "./ghostMath";
import { Label } from "./Label";
import { color } from "./palette";
import { toScene, type Origin, type Vec2 } from "./sceneMath";

export interface GhostSpec {
  track: string;
  incident: string;
  label: string;
  points: GhostPoint[];
}

/** The ghosts to draw now: the current top 3, mapped to tonight's identified target. */
export function currentGhosts(scene: Scene | null): { key: string; ghosts: GhostSpec[] } {
  const m = matchStore.getState().match;
  const f = replayStore.getState().features;
  const target = m?.target_asset_id ?? f[f.length - 1]?.target_asset_id ?? null;
  if (!m || !scene || isFenceTarget(target)) return { key: "", ghosts: [] };
  const a = scene.assets.find((x) => x.asset_id === target);
  if (!a) return { key: "", ghosts: [] };
  const c: Vec2 = [a.centroid_x_m, a.centroid_y_m];
  const g = ghostStore.getState();
  const ghosts: GhostSpec[] = [];
  for (const x of m.matches.slice(0, 3)) {
    g.load(x.track_id);
    const p = readyPath(g, x.track_id);
    if (!p) continue;
    ghosts.push({
      track: x.track_id,
      incident: x.incident_id,
      label: `${baseName(x.installation_id)}, ${localDate(x.local_start)}`,
      points: mapGhost(p, c),
    });
  }
  return { key: `${target}|${ghosts.map((x) => x.track).join("|")}`, ghosts };
}

const STORES = [matchStore, ghostStore, replayStore] as unknown as StoreApi<unknown>[];

function Ghost({ spec, index, origin }: { spec: GhostSpec; index: number; origin: Origin }) {
  const line = useMemo(() => {
    const pos = spec.points.flatMap((p) => toScene(p.x, p.y, p.alt, origin));
    const geom = new LineGeometry();
    geom.setPositions(pos);
    geom.setColors(new Array(pos.length).fill(0));
    const mat = new LineMaterial({
      vertexColors: true,
      linewidth: 2,
      transparent: true,
      depthWrite: false,
      blending: AdditiveBlending,
    });
    return new Line2(geom, mat);
  }, [spec, origin]);
  useEffect(() => () => {
    line.geometry.dispose();
    line.material.dispose();
  }, [line]);
  const born = useRef(performance.now());
  const done = useRef(false);
  const lastBright = useRef(-1);

  useFrame(({ size }) => {
    line.material.resolution.set(size.width, size.height);
    const reduce = reduceMotion(uiStore.getState());
    const hovered = matchStore.getState().hovered;
    const bright = hovered === null ? 0.75 : hovered === spec.track ? 1 : 0.35;
    const age = performance.now() - born.current;
    if (done.current && bright === lastBright.current) return;
    const attr = line.geometry.getAttribute("instanceColorStart") as InterleavedBufferAttribute;
    const arr = attr.data.array as Float32Array;
    const c = color("--afterglow");
    const nSeg = spec.points.length - 1;
    let finished = true;
    for (let k = 0; k < nSeg; k++) {
      // reduce motion: a plain fade over the dissolve time, no per-segment noise
      const a = reduce
        ? Math.min(1, Math.max(0, age / 600))
        : dissolveAlpha(k, index, age);
      if (a < 1) finished = false;
      const v = a * bright;
      // instanceColorStart / End interleave: [r g b (start) r g b (end)] per segment
      arr.set([c.r * v, c.g * v, c.b * v, c.r * v, c.g * v, c.b * v], k * 6);
    }
    attr.data.needsUpdate = true;
    done.current = finished;
    lastBright.current = bright;
  });

  const end = spec.points[spec.points.length - 1];
  const at = end ? toScene(end.x, end.y, end.alt, origin) : null;
  return (
    <group>
      <primitive object={line} />
      {at ? <Label text={spec.label} position={[at[0], at[1] + 6, at[2]]} px={12} tone="--afterglow" /> : null}
    </group>
  );
}

/**
 * Afterglow ghosts (§17.3): the current top 3's past flights in tonight's target frame,
 * dissolving in over 1.2 s, 150 ms apart; the hovered match's ghost brightens. Shown once
 * tonight's target is a named asset (D-128).
 */
export function Ghosts({ scene, origin }: { scene: Scene; origin: Origin }) {
  const g = useThrottledStores(STORES, () => currentGhosts(scene), 4);
  const shown = useThrottledStore(directorStore, (d) => revealOf(d.active, d.beat).ghosts, 4);
  if (!shown) return null;
  return (
    <group key={g.key}>
      {g.ghosts.map((spec, i) => (
        <Ghost key={spec.track} spec={spec} index={i} origin={origin} />
      ))}
    </group>
  );
}
