export const BEAM_MS = 1200;
const SEGMENTS = 40;

/** Brightness along a beam (u ∈ [0, 1] from the core) when its head is at `head`. */
export function beamGlow(u: number, head: number): number {
  if (u > head) return 0;
  return Math.exp(-((head - u) / 0.12) ** 2) * 0.9 + 0.15 * (1 - (head - u));
}

/** Where the three beams go: each top-3 ghost's point at the matched moment, else the target. */
export function beamTargets(scene: Scene, origin: Origin): Vec3[] {
  const m = matchStore.getState().match;
  if (!m) return [];
  const g = currentGhosts(scene);
  const out: Vec3[] = [];
  for (const x of m.matches.slice(0, 3)) {
    const spec = g.ghosts.find((s) => s.track === x.track_id);
    const w = Number(x.features["window_s"] ?? 0);
    if (spec) {
      const p = spec.points[alignedIndex(spec.points, x.window_offset_s + w)];
      if (p) {
        out.push(toScene(p.x, p.y, p.alt, origin));
        continue;
      }
    }
    const f = replayStore.getState().features;
    const tid = m.target_asset_id ?? f[f.length - 1]?.target_asset_id;
    const a = isFenceTarget(tid) ? null : scene.assets.find((s) => s.asset_id === tid);
    out.push(a ? toScene(a.centroid_x_m, a.centroid_y_m, 60, origin) : [0, 60, 0]);
  }
  return out;
}

/**
 * Core beams (§17.3, D-129): on each `match`, three afterglow beams leave the Kairos core toward
 * where the ghosts are (each past flight at the matched moment) over 1.2 s. Off in reduce motion
 * and Performance mode (they count as particles, §17.11).
 */
export function CoreBeams({ scene, origin }: { scene: Scene; origin: Origin }) {
  const lines = useMemo(
    () =>
      [0, 1, 2].map(() => {
        const g = new LineGeometry();
        g.setPositions(new Array((SEGMENTS + 1) * 3).fill(0));
        g.setColors(new Array((SEGMENTS + 1) * 3).fill(0));
        const mat = new LineMaterial({
          vertexColors: true,
          linewidth: 2,
          transparent: true,
          depthWrite: false,
          blending: AdditiveBlending,
        });
        const l = new Line2(g, mat);
        l.visible = false;
        l.frustumCulled = false;
        return l;
      }),
    [],
  );
  useEffect(
    () => () =>
      lines.forEach((l) => {
        l.geometry.dispose();
        l.material.dispose();
      }),
    [lines],
  );
  const seen = useRef(0);

  useFrame(({ size }) => {
    const ms = matchStore.getState();
    const d = directorStore.getState();
    const on = beamsOn(uiStore.getState()) && revealOf(d.active, d.beat).ghosts;
    const age = performance.now() - ms.matchWall;
    if (!on || !ms.matchWall || age > BEAM_MS) {
      for (const l of lines) l.visible = false;
      return;
    }
    if (seen.current !== ms.matchWall) {
      seen.current = ms.matchWall;
      const targets = beamTargets(scene, origin);
      lines.forEach((l, k) => {
        const to = targets[k];
        l.visible = !!to;
        if (!to) return;
        const lift = 0.18 * Math.hypot(to[0] - CORE_POSITION[0], to[2] - CORE_POSITION[2]);
        const pts: number[] = [];
        for (let i = 0; i <= SEGMENTS; i++) pts.push(...arcPoint(CORE_POSITION, to, i / SEGMENTS, lift));
        l.geometry.setPositions(pts);
        l.geometry.setColors(new Array(pts.length).fill(0));
        l.computeLineDistances();
      });
    }
    const head = Math.min(1, age / BEAM_MS);
    const fade = 1 - Math.max(0, (age - BEAM_MS * 0.8) / (BEAM_MS * 0.2));
    const c = color("--afterglow");
    for (const l of lines) {
      if (!l.visible) continue;
      l.material.resolution.set(size.width, size.height);
      const attr = l.geometry.getAttribute("instanceColorStart") as InterleavedBufferAttribute;
      const arr = attr.data.array as Float32Array;
      for (let k = 0; k < SEGMENTS; k++) {
        const v0 = beamGlow(k / SEGMENTS, head) * fade;
        const v1 = beamGlow((k + 1) / SEGMENTS, head) * fade;
        arr.set([c.r * v0, c.g * v0, c.b * v0, c.r * v1, c.g * v1, c.b * v1], k * 6);
      }
      attr.data.needsUpdate = true;
    }
  });

  return (
    <group>
      {lines.map((l, k) => (
        <primitive key={k} object={l} />
      ))}
    </group>
  );
}
