  if (!on) return null;
  return (
    <EffectComposer multisampling={0}>
      <Bloom mipmapBlur luminanceThreshold={0.2} luminanceSmoothing={0.3} intensity={0.7} />
      <Vignette offset={0.3} darkness={0.45} />
      <Grain amount={0.03} />
    </EffectComposer>
  );
}
EOF

