          <div>
            <h1 id="explainer-title" className="text-24 font-bold text-ink-hi">
              {name ? `Why ${name} matches tonight` : "Match explainer"}
            </h1>
            <p className="text-15 text-ink-mid">
              {incident ?? "–"} at {tPlus(doc?.t_s ?? at)}
