                className="w-24 rounded-button border border-hairline bg-scope px-2 py-1 font-mono text-13 text-ink-hi"
              />
            </label>
            <button type="submit" className="rounded-button border border-hairline px-3 py-1 text-13 text-ink-hi hover:border-flash">
