            </button>
          </form>
        </header>
        {error ? (
          <p role="alert" className="text-15 text-alert">
            {error}
          </p>
        ) : null}
        <section aria-labelledby="lens-title" className="rounded-panel border border-hairline bg-glass p-3 backdrop-blur-glass">
          <h2 id="lens-title" className="mb-2 text-13 font-bold text-ink-mid">
