              dtw={dtw && dtw.match_track_id === track ? dtw : null}
              matches={matches}
              track={track}
              channel={channel}
              mode={mode}
              reduce={reduce}
              variant="full"
              onMode={setMode}
              onTrack={(tr) => incident && navigate(href(incident, at, tr))}
              onChannel={setChannel}
            />
          ) : (
            <p className="text-13 text-ink-mid">Loading the matches</p>
          )}
        </section>
        {doc ? (
          <div className="grid grid-cols-1 gap-4 2xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
            <section aria-labelledby="flights-title" className="rounded-panel border border-hairline bg-glass p-3 backdrop-blur-glass">
              <h2 id="flights-title" className="mb-2 text-13 font-bold text-ink-mid">
                Both flights, target-relative
              </h2>
              <FlightPair
                tonight={doc.tonight}
                past={doc.past}
                pastTitle={`${name ?? doc.past.incident_id}, whole flight`}
                segment={[doc.segment.start_s, doc.segment.end_s]}
                alignment={doc.alignment ? [doc.alignment.start_s, doc.alignment.end_s] : null}
              />
              <p className="mt-2 text-13 text-ink-mid">
                Bold: the matcher's {doc.window_s} s window on the past flight, from{" "}
                {tPlus(doc.segment.start_s)} to {tPlus(doc.segment.end_s)}.
                {doc.alignment
                  ? ` Dashed: where tonight's distance-to-target window aligns inside the whole flight, ${tPlus(doc.alignment.start_s)} to ${tPlus(doc.alignment.end_s)}.`
                  : ""}
              </p>
            </section>
            <section aria-labelledby="fusion-title" className="rounded-panel border border-hairline bg-glass p-3 backdrop-blur-glass">
              <h2 id="fusion-title" className="mb-2 text-13 font-bold text-ink-mid">
                What the score is made of
              </h2>
              <Contributions rows={doc.contributions} intercept={doc.intercept} logit={doc.logit} score={doc.score} />
              {m ? (
                <div className="mt-3 flex flex-col gap-1.5">
                  <ul aria-label="Reasons" className="flex flex-wrap gap-1">
                    {m.reasons.map((r) => (
                      <li key={r} className="rounded-chip border border-hairline px-2 py-0.5 text-12 text-ink-hi">
