                      </li>
                    ))}
                  </ul>
                  <p className={`text-13 ${m.memory_status.startsWith("Closed") ? "text-afterglow" : "text-ink-mid"}`}>
                    {m.memory_status}
                  </p>
                </div>
              ) : null}
            </section>
          </div>
        ) : null}
      </div>
    </main>
  );
}
