  }, [caseId]);

  useEffect(() => {
    setFiles([]);
    setDone(null);
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (!caseId && cases.length) navigate(`/evidence?case=${cases[0]?.case_id ?? ""}`, true);
  }, [caseId, cases]);

  useEffect(() => {
    if (current) directorStore.getState().setFacts({ pending: current.pending });
  }, [current]);

