                    <span aria-hidden="true" className="mr-1 font-mono">{s.icon}</span>
                    {s.word}
                  </p>
                </li>
              );
            })}
          </ul>
        ) : null}
        {r ? (
          <div className="grid grid-cols-1 gap-4 xl:grid-cols-3">
            <section aria-labelledby="ch-recall" className="rounded-panel border border-hairline bg-glass p-3 backdrop-blur-glass">
              <h2 id="ch-recall" className="mb-2 text-13 font-bold text-ink-mid">Recall against seconds of flight (probers)</h2>
