    expect(parts[0]?.[1]).toEqual([0, 5]);
    expect(Math.hypot(...(parts[0]?.[0] as Vec2))).toBeCloseTo(10);
    expect((parts[0]?.at(-1) as Vec2)[1]).toBeCloseTo(10);
    // starting inside
    expect(clipPolylineToCircle([[0, 0], [20, 0]], [0, 0], 10)).toEqual([[[0, 0], [10, 0]]]);
