    expect(JSON.parse(String(init.body))).toEqual({
      proposal_seq: 4683,
      decision: "approve",
      analyst: ANALYST,
      clock: "2026-08-29T02:41:40.000Z",
    });
    expect(ANALYST).toBe("demo");
  });

  it("errors carry the server's message", async () => {
    setFetch(
      (async () =>
        new Response(JSON.stringify({ detail: "proposal 7 is already decided" }), {
import { beforeEach, describe, expect, it } from "vitest";

import { decisionOf, matchStore, top3Key } from "../src/state/matchStore";
import { match } from "./fixtures";

const s = () => matchStore.getState();

beforeEach(() => {
  matchStore.setState({ entrance: 0, top3: "", decisions: {}, busy: {} });
  s().clear();
});

describe("matchStore", () => {
  it("a match replaces the list", () => {
    s().apply(match(90));
    s().apply(match(95, ["P1-DELTA-260419", "P1-CHARLIE-260710", "P1-ALPHA-260303"]));
    expect(s().match?.t_s).toBe(95);
    expect(s().match?.matches[1]?.incident_id).toBe("P1-CHARLIE-260710");
  });

  it("the entrance runs only for a new top-3 set", () => {
    s().apply(match(90));
    expect(s().entrance).toBe(1);
    s().apply(match(95, ["P1-ALPHA-260502", "P1-DELTA-260419", "P1-ALPHA-260303"]));
    expect(s().entrance).toBe(1); // same set, another order
    s().apply(match(100, ["P1-DELTA-260419", "P1-ALPHA-260303", "P1-CHARLIE-260710"]));
    expect(s().entrance).toBe(2);
    expect(top3Key(null)).toBe("");
  });

import { beforeEach, describe, expect, it } from "vitest";

import {
  PACKET_BUDGET,
  effectsOn,
  packetBudget,
  reduceMotion,
  uiStore,
} from "../src/state/uiStore";

const s = () => uiStore.getState();

beforeEach(() => uiStore.setState({ osReduce: false, userReduce: null, perfLevel: 0 }));

describe("uiStore", () => {
  it("follows the OS until M toggles reduce motion", () => {
    s().setOsReduce(true);
    expect(reduceMotion(s())).toBe(true);
    s().toggleReduce();
    expect(reduceMotion(s())).toBe(false);
    s().toggleReduce();
    expect(reduceMotion(s())).toBe(true);
  });

  it("effects and packets follow motion and performance levels", () => {
    expect(effectsOn(s())).toBe(true);
    expect(packetBudget(s())).toBe(PACKET_BUDGET);
    s().setPerfLevel(1);
    expect(effectsOn(s())).toBe(false);
    expect(packetBudget(s())).toBe(PACKET_BUDGET);
    s().setPerfLevel(2);
    expect(packetBudget(s())).toBe(PACKET_BUDGET / 2);
    s().setOsReduce(true);
    expect(packetBudget(s())).toBe(0);
  });
});

